import fs from "fs";
import pdf from "pdf-parse/lib/pdf-parse.js";
import ExcelJS from "exceljs";

// --- 1. Extract text from page 1 only ---
const dataBuffer = fs.readFileSync("/workspace/testbed/docs/handbook.pdf");

// pdf-parse supports a pagerender option; we only keep page 1
const options = {
  // Return text only for page 1, empty string for others
  pagerender: function (pageData) {
    if (pageData.pageIndex === 0) {
      // pageIndex is 0-based
      return pageData.getTextContent().then((textContent) =>
        textContent.items.map((item) => item.str).join(" ")
      );
    }
    return Promise.resolve("");
  },
};

const pdfData = await pdf(dataBuffer, options);
const page1Text = pdfData.text.trim();

console.log("=== Extracted text from page 1 ===");
console.log(page1Text);
console.log("==================================");

// --- 2. Write to Excel ---
const workbook = new ExcelJS.Workbook();
const sheet = workbook.addWorksheet("Page 1 Text");

// Header row
sheet.columns = [
  { header: "Line", key: "line", width: 8 },
  { header: "Text", key: "text", width: 120 },
];
sheet.getRow(1).font = { bold: true };

// Split text into lines and add a row per line
const lines = page1Text.split(/\n/);
lines.forEach((line, i) => {
  sheet.addRow({ line: i + 1, text: line });
});

const outPath = "/workspace/handbook_page1.xlsx";
await workbook.xlsx.writeFile(outPath);
console.log(`\nExcel file written to: ${outPath}`);

