const fs = require("fs");
const ExcelJS = require("exceljs");

async function extractPage1(pdfPath) {
  // Dynamic import for pdfjs-dist (ESM-only)
  const pdfjsLib = await import("pdfjs-dist/legacy/build/pdf.mjs");

  const data = new Uint8Array(fs.readFileSync(pdfPath));
  const doc = await pdfjsLib.getDocument({ data }).promise;
  const page = await doc.getPage(1);
  const content = await page.getTextContent();

  // Join text items, preserving line structure via transform y-coords
  const lines = [];
  let lastY = null;
  let currentLine = "";

  for (const item of content.items) {
    if (item.str === undefined) continue;
    const y = item.transform[5];
    if (lastY !== null && Math.abs(y - lastY) > 2) {
      lines.push(currentLine);
      currentLine = item.str;
    } else {
      currentLine += item.str;
    }
    lastY = y;
  }
  if (currentLine) lines.push(currentLine);

  return lines;
}

(async () => {
  const pdfPath = "/workspace/testbed/docs/handbook.pdf";
  console.log("Extracting text from page 1...\n");

  const lines = await extractPage1(pdfPath);

  console.log("=== Extracted text from page 1 ===");
  lines.forEach((l, i) => console.log(`${i + 1}: ${l}`));
  console.log(`=== ${lines.length} lines total ===\n`);

  // Write to Excel
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1 Text");

  sheet.columns = [
    { header: "Line", key: "line", width: 8 },
    { header: "Text", key: "text", width: 120 },
  ];
  sheet.getRow(1).font = { bold: true };

  lines.forEach((text, i) => {
    sheet.addRow({ line: i + 1, text });
  });

  const outPath = "/workspace/handbook_page1.xlsx";
  await workbook.xlsx.writeFile(outPath);
  console.log(`Excel file written to: ${outPath}`);
})();

